  function home(onlyTracks=false){
    const earned=state.user?.certificates.length||0;
    const biOnly=state.catalog.tracks.length===1&&state.catalog.tracks[0].id==='bi',techOnly=state.catalog.tracks.length===1&&!!state.catalog.tracks[0].trainingOnly;
    const cards=state.catalog.tracks.map((track,index)=>{
      const cert=certificateFor(track.id),allowed=trackAllowed(track.id),open=state.user?.attempts.find(a=>a.track_id===track.id&&a.status==='open');
      return `<article class="track-card channel-${track.id}"><div class="track-top"><div><span class="overline">TRILHA ${String(index+1).padStart(2,'0')}</span><h3>${esc(track.name)}</h3></div><img src="/assets/badges/${track.id}.svg" alt="Insígnia ${esc(track.badge)}" width="95" height="112"></div><div class="track-body"><p>${esc(track.description)}</p><div class="track-meta"><span>${icon('list')} ${track.trainingOnly?'5 volumes':track.questionCount+' perguntas'}</span><span>${icon('clock')} ${track.trainingOnly?'Formação em andamento':'~'+track.estimatedMinutes+' min'}</span></div><span class="track-status ${cert?'passed':''}">${track.trainingOnly?'Percurso de estudo · avaliações em revisão':cert?'Trilha conquistada · '+cert.score+'%':open?'Avaliação em andamento':allowed?'Insígnia: '+esc(track.badge):'O gestor ainda não liberou esta trilha'}</span>${hasAccess('assessments')||track.trainingOnly?`<a class="game-text-link" href="#percurso/${track.id}">Avançar com o Starzinho ${icon('arrow')}</a>`:''}<div class="track-action"><a class="button" href="#trilha/${track.id}">${track.trainingOnly?'Acessar formação':cert?'Ver trilha':open?'Continuar trilha':hasAccess('assessments')?'Começar trilha':'Ver trilha'} ${icon('arrow')}</a></div></div></article>`;
    }).join('');
    commitView(`${onlyTracks?'':state.onboardingPanel?.summary()||''}${onlyTracks?`<section class="page-top"><div class="wrap"><span class="overline muted">${biOnly?'FORMAÇÃO EM DADOS':techOnly?'FORMAÇÃO TECH':'SEU DESENVOLVIMENTO ST1'}</span><h1>Minhas trilhas.</h1><p>Escolha uma especialidade, estude os materiais e avance na sua certificação.</p></div></section>`:`<section class="hero"><div class="wrap"><div class="hero-grid"><div class="hero-copy"><span class="overline">${biOnly?'CAPACITAÇÃO EM DADOS PARA DECIDIR MELHOR':techOnly?'FORMAÇÃO TÉCNICA APLICADA':'CAPACITAÇÃO QUE VIRA RESULTADO'}</span><h1>${biOnly?'Do dado à decisão.':techOnly?'Do dado ao banco.':'Do catálogo à venda.'}<br><span>${biOnly?'Construa análises confiáveis.':techOnly?'Estruture dados confiáveis.':'Prove que você domina.'}</span></h1><p>${biOnly?'Aprenda a preparar dados, modelar indicadores, usar DAX e publicar dashboards claros e confiáveis.':techOnly?'Aprenda fundamentos relacionais, SQL, integridade, desempenho, segurança e integração com BI em cinco volumes progressivos.':'Conheça a oferta, resolva situações reais e conquiste a certificação do seu canal. Cada trilha tem uma prova, uma insígnia e um certificado próprios.'}</p><div class="hero-actions"><a class="button button-primary" href="#trilhas">Explorar trilhas ${icon('arrow')}</a>${hasAccess('materials')?`<a class="button button-outline-light" href="#conteudos">Explorar conteúdos ${icon('book')}</a>`:''}</div><div class="hero-method"><span><strong>01</strong> ${biOnly?'PREPARE OS DADOS':techOnly?'MODELE OS DADOS':'ESTUDE'}</span><span><strong>02</strong> ${biOnly?'MODELE E ANALISE':techOnly?'CONSULTE COM SQL':'APLIQUE NA PROVA'}</span><span><strong>03</strong> ${biOnly?'PUBLIQUE':techOnly?'INTEGRE AO BI':'CONQUISTE'}</span></div></div><aside class="passport" aria-label="Seu progresso nas certificações"><div class="passport-head">${icon('award')}<div><div class="passport-title">${biOnly?'Passaporte de BI':techOnly?'Formação Tech':'Passaporte ST1'}</div><span class="passport-caption">COMPETÊNCIA COMPROVADA POR TRILHA</span></div></div><div class="passport-number"><strong>${String(earned).padStart(2,'0')}</strong><span>/ ${String(state.catalog.tracks.length).padStart(2,'0')} conquistas</span></div><div class="passport-slots">${state.catalog.tracks.map((t,i)=>`<span class="${certificateFor(t.id)?'unlocked':''}" aria-label="${esc(t.name)}: ${certificateFor(t.id)?'conquistada':'a conquistar'}">${certificateFor(t.id)?icon('check'):String(i+1).padStart(2,'0')}</span>`).join('')}</div><p>${state.user?'Seu progresso é salvo na sua conta. Você pode continuar de onde parou.':'Entre com seu convite pessoal para registrar o resultado e receber suas conquistas.'}</p></aside></div></div></section>`}<section class="library" id="trilhas"><div class="wrap"><div class="section-title"><div><span class="overline muted">${biOnly?'DADOS EM CADA ETAPA':techOnly?'CINCO VOLUMES. UMA BASE SÓLIDA.':'CADA ESPECIALIDADE. UMA CONQUISTA.'}</span><h2>Escolha sua próxima trilha.</h2></div><p>${biOnly?'Avance pelos materiais, aulas, laboratórios e avaliações até publicar seu projeto analítico.':techOnly?'Avance pelos volumes visuais; as avaliações estão em revisão interna.':'Explore os conteúdos, aplique o conhecimento e avance nas certificações disponíveis para você.'}</p></div><div class="track-grid">${cards||'<div class="empty-panel"><h3>Nenhuma trilha liberada.</h3><p>O Admin precisa selecionar as trilhas da sua conta na área de Acessos.</p></div>'}</div><div class="criteria-strip">${icon('shield')}<div><strong>${techOnly?'Avaliações em revisão; formação disponível por estudo.':biOnly?'Aprovação exige análise consistente e regras críticas corretas.':'Aprovação exige conhecimento e conduta correta.'}</strong><p>${techOnly?'Os rascunhos privados aguardam revisão acadêmica antes de qualquer avaliação ou certificado.':`São ${state.catalog.minimumPercent}% de acertos: pelo menos 16 das 20 perguntas. Todas as regras críticas também precisam estar corretas. ${biOnly?'Use as devolutivas para reforçar os conceitos e validar cada etapa do percurso.':'Use as explicações para reforçar o conhecimento e retomar os materiais quando necessário.'}`}</p></div></div></div></section>`);
  }
  async function detail(id){
    const track=trackFor(id);if(!track)return restricted('Trilha não liberada.','O Admin define quais trilhas aparecem para sua conta.');
    if(!state.user)return restricted('Entre para acessar a trilha.','Use seu convite pessoal ou entre na sua conta para ver o conteúdo liberado pelo Admin.',true);

    const certificate=certificateFor(id),allowed=trackAllowed(id)&&hasAccess('assessments'),open=state.user?.attempts.find(a=>a.track_id===id&&a.status==='open'),limit=state.user?.attemptLimits?.[id];
    const courseFlow=(id==='bi'&&allowed||track.trainingOnly&&hasAccess('materials'))?await api(`/api/learning-flows/percurso-${id}`):null,certificateReady=!courseFlow||courseFlow.nodes.find(node=>node.kind==='certificate')?.locked===false;
    let lessons=hasAccess('materials')?await (await contentPanel()).publishedLessons(id):'';
    if(location.hash!=='#trilha/'+id)return;
    const topics=track.id==='bi'?'Fundamentos de BI, preparação no Power Query, modelagem dimensional, DAX, visualização, segurança, desempenho e publicação.':track.id==='pme'?'Planos e adicionais, condições do contrato e aplicativos.':'Pacotes, aplicativos e decisões de venda, conforme os materiais desta trilha.';
    const bi=id==='bi',studyOnly=!!track.trainingOnly;
    commitView(`<section class="page-top"><div class="wrap"><div class="breadcrumbs"><a href="#trilhas">Trilhas</a><span>/</span><span>${esc(track.name)}</span></div><span class="overline muted">${bi||studyOnly?'FORMAÇÃO':'TRILHA DE CERTIFICAÇÃO'}</span><h1>${bi?'Analise dados com confiança.':studyOnly?'Do dado ao banco de dados.':'Domine o canal '+esc(track.name)+'.'}</h1><p>${esc(track.description)} ${bi?'Prepare os dados, construa o modelo, valide as métricas e publique uma análise que apoie decisões.':studyOnly?'Estude os cinco volumes visuais, pratique com a base sintética e avance do nível inicial ao projeto aplicado.':'Estude o material e mostre que sabe o que apresentar, o que confirmar e como conduzir a venda.'}</p></div></section><div class="wrap detail-content"><section><div class="section-title"><div><span class="overline muted">${bi||studyOnly?'DO NIVELAMENTO AO PROJETO':'SEU PONTO DE PARTIDA'}</span><h2>${hasAccess('materials')?'O que estudar.':'Sua trilha.'}</h2></div></div><div class="lesson-list">${hasAccess('materials')?lessons:'<div class="empty-panel"><h3>Materiais não liberados.</h3><p>O Admin controla a liberação dos materiais de estudo para sua conta.</p></div>'}</div><div class="warning-box"><strong>${studyOnly?'Avaliações em revisão interna':'O que cai na avaliação'}</strong>${studyOnly?'As avaliações ainda são privadas e não emitem certificado. A formação cobre fundamentos, modelagem, SQL, histórico, transações, desempenho, segurança, continuidade e integração com BI.':topics+' '+(bi?'Cada etapa combina um caderno visual, três aulas e um laboratório.':'As questões trazem situações práticas e alternativas que mudam de ordem a cada tentativa.')}${['digital','elite','indoor'].includes(id)?'<br><strong>Regra crítica: 2.000 Mega só pode ser vendido no condomínio DAHMAS.</strong>':''}</div></section><aside class="assessment-panel channel-${id}"><img src="/assets/badges/${id}.svg" width="106" height="124" alt="${esc(track.badge)}"><h2>${esc(track.badge)}</h2><p>${studyOnly?'A formação está disponível; avaliação e certificação seguem em revisão.':bi?'Conclua os 16 módulos para liberar a certificação final.':'Conquiste esta insígnia e o certificado da trilha.'}</p>${studyOnly?`<a class="button button-primary" href="#percurso/tech">Abrir percurso de estudo ${icon('arrow')}</a>`:`<ul class="rules-list"><li>20 perguntas de escolha única.</li><li>Pelo menos 16 respostas corretas.</li><li>Acerto em todas as ${track.criticalCount} regras críticas.</li><li>Respostas salvas ao avançar. Sem limite de tempo.</li><li>Máximo de 3 tentativas iniciais. Outras somente com autorização do Supervisor ou Admin.</li></ul>${limit?`<p role="status">${limit.used} de ${limit.max} tentativas utilizadas. ${limit.remaining} restante(s).</p>`:''}${limit?.requiresAuthorization&&!open?'<p role="alert">Limite de tentativas atingido. Solicite uma nova autorização ao seu Supervisor ou Admin.</p>':''}${allowed&&certificateReady&&(!limit?.blocked||open||limit?.inProgress)?`<button type="button" class="button button-primary" data-start="${id}">${certificate?'Refazer para praticar':open?'Continuar avaliação':'Fazer avaliação'} ${icon('arrow')}</button>`:bi&&allowed?`<a class="button button-primary" href="#percurso/bi">Avançar pelos módulos ${icon('arrow')}</a>`:'<p>A prova desta trilha ainda não foi liberada para sua conta.</p>'}`}${certificate?`<a href="/api/certificates/${certificate.id}/pdf" class="button button-outline-light">Baixar certificado ${icon('download')}</a>`:''}</aside></div>`);

  }
  function exam(){
    const attempt=state.attempt,track=trackFor(attempt.trackId),q=attempt.questions[state.questionIndex],last=state.questionIndex===attempt.questions.length-1;
    if(attempt.status==='complete')return resultPage(attempt);
    commitView(`<div class="wrap exam-shell"><div class="exam-topline"><h1>${esc(track.name)} · Avaliação</h1><a href="#trilha/${track.id}">${icon('back')} Sair e continuar depois</a></div><div class="exam-progress"><progress value="${Object.keys(attempt.answers).length}" max="${attempt.questions.length}" aria-label="Perguntas respondidas"></progress><span>${state.questionIndex+1} de ${attempt.questions.length}</span></div><div class="exam-error" id="exam-error" role="alert" hidden></div><article class="question-card"><div class="question-label"><span>${esc(q.topic)}</span><span>PERGUNTA ${String(state.questionIndex+1).padStart(2,'0')}</span>${q.critical?'<span class="critical-label">Regra crítica · acerto obrigatório</span>':''}</div><h2 id="question-title">${esc(q.stem)}</h2><fieldset class="answers" aria-labelledby="question-title"><legend class="sr-only">Escolha uma resposta</legend>${q.options.map((option,index)=>`<label class="answer-option"><input type="radio" name="answer" value="${esc(option.id)}" ${attempt.answers[q.id]===option.id?'checked':''}><span class="option-letter" aria-hidden="true">${String.fromCharCode(65+index)}</span><span>${esc(option.text)}</span></label>`).join('')}</fieldset><div class="question-actions"><button class="button button-secondary" type="button" data-exam-back ${state.questionIndex===0?'disabled':''}>${icon('back')} Anterior</button><button class="button button-primary" type="button" data-exam-next ${attempt.answers[q.id]?'':'disabled'}>${last?'Concluir avaliação':'Próxima pergunta'} ${icon('arrow')}</button></div></article><div class="question-index" aria-label="Ir para uma pergunta">${attempt.questions.map((item,index)=>`<button type="button" data-question="${index}" class="${attempt.answers[item.id]?'answered ':''}${index===state.questionIndex?'current':''}" aria-label="Pergunta ${index+1}${attempt.answers[item.id]?', respondida':''}" ${index===state.questionIndex?'aria-current="step"':''}>${index+1}</button>`).join('')}</div><p class="saved-note">Suas respostas são salvas ao avançar. A correção aparece depois da conclusão.</p></div>`);
  }
  async function saveProgress(){
    if(state.saving)return false;
    state.saving=true;
    document.querySelectorAll('[data-exam-next],[data-exam-back],[data-question]').forEach(button=>button.disabled=true);
    try{const result=await api(`/api/attempts/${state.attempt.id}`,{method:'PUT',body:{answers:state.attempt.answers,revision:state.attempt.revision}});state.attempt.revision=result.revision;return true;}catch(error){const box=document.querySelector('#exam-error');if(box){box.textContent=error.message;box.hidden=false;}else toast(error.message);return false;}finally{state.saving=false;document.querySelectorAll('[data-exam-next],[data-exam-back],[data-question]').forEach(button=>button.disabled=false);}
  }
  function resultPage(attempt){
    const result=attempt.result,track=trackFor(attempt.trackId),limit=state.user?.attemptLimits?.[attempt.trackId],criticalTotal=attempt.questions.filter(q=>q.critical).length;
    const title=result.approved?'Trilha conquistada.':result.score>=80?'Uma regra precisa de revisão.':'Revise. Tente de novo.';
    const description=result.approved?`Você conquistou ${track.badge}. Seu resultado ficou registrado e o certificado está disponível na sua conta.`:result.failedCritical?`Você acertou ${result.correct} das ${result.total} perguntas, mas errou ${result.failedCritical} regra${result.failedCritical===1?' crítica':'s críticas'}. Revise os pontos abaixo antes de tentar novamente.`:`Você precisa de pelo menos 16 acertos em 20. Veja a explicação das respostas e volte aos materiais para uma nova tentativa.`;
    const reviews=result.details.map(detail=>`<details class="review-question ${detail.correct?'passed-question':''}" ${detail.critical&&!detail.correct?'open':''}><summary><span class="review-tag">${detail.correct?'Resposta correta':detail.critical?'Revisar regra crítica':'Revisar este ponto'}</span>${esc(detail.stem)}</summary><div class="review-answer"><div>Sua resposta: ${esc(detail.chosen)}</div><div class="expected-answer">Resposta correta: ${esc(detail.expected)}</div><p>${esc(detail.explanation)}</p>${hasAccess('materials')?`<a href="${sourceUrl(detail.source)}" target="_blank" rel="noopener">Rever no material · página ${detail.source.page} ${icon('link')}</a>`:''}</div></details>`).join('');
    commitView(`<section class="result-hero"><div class="wrap result-grid"><div><span class="overline">${result.approved?'CERTIFICAÇÃO / '+esc(track.name.toUpperCase()):'DEVOLUTIVA / '+esc(track.name.toUpperCase())}</span><h1>${title}</h1><p>${esc(description)}</p><div class="result-actions">${result.certificate&&hasAccess('conquests')?`<a href="/api/certificates/${result.certificate.id}/pdf" class="button button-primary">Baixar certificado ${icon('download')}</a><a href="#conquistas" class="button button-outline-light">Minhas conquistas ${icon('award')}</a>`:`<a href="#trilha/${track.id}" class="button button-primary">Rever a trilha ${icon('book')}</a>${limit?.requiresAuthorization?'<p role="alert">Suas tentativas acabaram. Peça uma nova autorização ao Supervisor ou Admin.</p>':`<button class="button button-outline-light" type="button" data-start="${track.id}">Tentar novamente ${icon('arrow')}</button>`}`}</div></div><img src="/assets/badges/${track.id}.svg" alt="${result.approved?esc(track.badge):'Insígnia da trilha a conquistar'}" width="165" height="197"></div></section><section class="wrap result-body"><div class="result-stats"><div class="result-stat"><span>Nota da avaliação</span><strong>${result.score}%</strong><small>Mínimo: 80%</small></div><div class="result-stat"><span>Respostas corretas</span><strong>${result.correct}/${result.total}</strong><small>${track.id==='bi'?'Questões de análise de dados':'Questões práticas de venda'}</small></div><div class="result-stat"><span>Regras críticas</span><strong>${criticalTotal-result.failedCritical}/${criticalTotal}</strong><small>Todas precisam estar corretas</small></div></div><h2>Entenda suas respostas.</h2><p>Use a explicação para reforçar o conhecimento. Cada resposta leva ao ponto certo do material.</p>${reviews}</section>`);
  }
  function conquests(){
    if(!state.user){commitView(`<section class="page-top"><div class="wrap"><span class="overline muted">SEU PASSAPORTE COMERCIAL</span><h1>Suas conquistas, no seu nome.</h1><p>As insígnias e os certificados ficam vinculados à sua conta da ST1 Academy.</p></div></section><section class="wrap library"><div class="empty-panel"><h2>Entre para ver seu progresso.</h2><p>A aprovação exige 80% de acertos e todas as regras críticas corretas. Seu gestor fornece o convite de primeiro acesso.</p><button class="button button-primary" type="button" data-login>Entrar na ST1 Academy ${icon('arrow')}</button></div></section>`);return;}
    if(!hasAccess('conquests'))return restricted('Conquistas não liberadas.','O Admin ainda não liberou esta área para sua conta.');
    const cards=state.catalog.tracks.map(track=>{const cert=certificateFor(track.id);return `<article class="conquest-card ${cert?'':'locked'}"><img src="/assets/badges/${track.id}.svg" alt="${esc(track.badge)}" width="134" height="158"><h2>${esc(track.badge)}</h2><p>${cert?`Trilha conquistada · ${cert.score}% de acertos<br>${new Date(cert.issued_at).toLocaleDateString('pt-BR',{timeZone:'America/Fortaleza'})}`:'Conquiste esta insígnia aprovando na avaliação da trilha.'}</p>${cert?`<a class="button button-dark" href="/api/certificates/${cert.id}/pdf">Baixar certificado ${icon('download')}</a>${hasAccess('community')&&track.id!=='bi'?`<button type="button" class="button button-secondary" data-share-cert="${cert.id}">Compartilhar no squad ${icon('arrow')}</button>`:''}<a class="button button-secondary" href="/assets/badges/${track.id}.svg" download>Salvar insígnia ${icon('award')}</a>`:`<span class="locked-text">${icon('lock')} Ainda não conquistada</span><a class="button button-secondary" href="#trilha/${track.id}">Ver trilha ${icon('arrow')}</a>`}</article>`;}).join('');
    const biOnly=state.catalog.tracks.length===1&&state.catalog.tracks[0].id==='bi';
    commitView(`<section class="page-top"><div class="wrap"><span class="overline muted">${biOnly?'PASSAPORTE DE BI':'PASSAPORTE ST1'}</span><h1>Minhas conquistas.</h1><p>${esc(state.user.name)}, você conquistou ${state.user.certificates.length} de ${state.catalog.tracks.length} trilhas liberadas. ${biOnly?'Cada aprovação comprova seu domínio de dados, análise e Power BI.':'Cada aprovação representa domínio de uma especialidade da ST1 Academy.'}</p></div></section><section class="wrap conquests-grid">${cards}</section>${state.user.recognitions?.length?`<section class="wrap manage-additional-conquests"><span class="overline muted">CADA AVANÇO TEM SEU VALOR</span><h2>Reconhecimentos da Academy.</h2><div class="conquests-grid">${state.user.recognitions.map(r=>`<article class="conquest-card"><img src="${r.artUrl}" alt="${esc(r.title)}"><h3>${esc(r.title)}</h3><p>${new Date(r.issuedAt).toLocaleDateString('pt-BR')} · ${r.kind==='certificates'?'Certificado':'Insígnia'}</p>${r.pdfUrl?`<a class="button button-dark" href="${r.pdfUrl}">Baixar certificado ${icon('download')}</a>`:''}<a class="button button-secondary" href="${r.artUrl}" download>Salvar insígnia ${icon('award')}</a></article>`).join('')}</div></section>`:''}`);
  }
  async function adminPage(){
    const supervisor=state.user?.role==='supervisor';
    if(!['admin','supervisor'].includes(state.user?.role)||!hasAccess('team_results'))return restricted('Acompanhamento não liberado.','O painel da equipe é liberado pelo Admin para os supervisores responsáveis.',!state.user);
    const base=supervisor?'/api/team':'/api/admin',report=await api(`${base}/report`);
    const attempts=report.attempts||[],certificates=report.certificateRecords||[],tracks=state.catalog.tracks||[];
    const completed=attempts.filter(item=>item.status==='complete'&&item.result),approved=completed.filter(item=>item.result.approved),inProgress=attempts.filter(item=>item.status==='open'),needsReview=completed.filter(item=>!item.result.approved);
    const progressedPeople=new Set([...completed.map(item=>item.user_id),...certificates.map(item=>item.user_id)]);
    const formatPercent=value=>`${Number(value).toLocaleString('pt-BR',{maximumFractionDigits:1})}%`;
    const averageScore=items=>{const scores=items.map(item=>item.result?.score).filter(score=>score!==null&&score!==undefined&&Number.isFinite(Number(score))).map(Number);return scores.length?formatPercent(scores.reduce((sum,score)=>sum+score,0)/scores.length):'—';};
    const formatDate=value=>{if(!value)return'—';const date=new Date(value);return Number.isNaN(date.getTime())?'—':date.toLocaleDateString('pt-BR',{timeZone:'America/Fortaleza'});};
    const trackSummaries=tracks.map(track=>{
      const items=attempts.filter(item=>item.track_id===track.id),finished=items.filter(item=>item.status==='complete'&&item.result),passed=finished.filter(item=>item.result.approved),open=items.filter(item=>item.status==='open'),trackCertificates=certificates.filter(item=>item.track_id===track.id),rate=finished.length?Math.round(passed.length/finished.length*100):0;
      return `<article class="results-track-card"><div class="results-track-head"><img src="/assets/badges/${esc(track.id)}.svg" alt="" width="54" height="64"><div><span class="overline muted">DESEMPENHO DA TRILHA</span><h3>${esc(track.name)}</h3></div><strong class="results-track-rate">${finished.length?rate+'%':'—'}</strong></div><div class="results-track-meter" role="meter" aria-label="Taxa de aprovação em ${esc(track.name)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${rate}"><span style="width:${rate}%"></span></div><div class="results-track-facts"><div><strong>${finished.length}</strong><span>Avaliações concluídas</span></div><div><strong>${trackCertificates.length}</strong><span>Certificados</span></div><div><strong>${open.length}</strong><span>Em andamento</span></div></div><p class="results-track-foot">${finished.length?`${passed.length} aprovação(ões) · nota média ${averageScore(finished)}`:'Ainda não há avaliações concluídas nesta trilha.'}</p></article>`;
    }).join('');
    const certificateCards=certificates.map(certificate=>`<article class="results-certificate-card"><img src="/assets/badges/${esc(certificate.track_id)}.svg" alt="" width="64" height="76"><div class="results-certificate-person"><span class="overline muted">CERTIFICADO EMITIDO</span><h3>${esc(certificate.name)}</h3><p>${esc(certificate.email)}</p><div class="results-certificate-meta"><span>${esc(trackFor(certificate.track_id)?.name||certificate.track_id)}</span><span>${formatDate(certificate.issued_at)}</span></div></div><div class="results-certificate-score"><strong>${certificate.score===null||certificate.score===undefined?'—':formatPercent(certificate.score)}</strong><span>nota</span><a class="button button-secondary button-small" href="/api/certificates/${esc(certificate.id)}/pdf">Baixar PDF ${icon('download')}</a></div></article>`).join('');
    const rows=attempts.map(attempt=>{
      const finished=attempt.status==='complete'&&attempt.result,passed=!!attempt.result?.approved,statusLabel=finished?(passed?'Aprovado':'Revisar conteúdo'):(attempt.status==='open'?'Em andamento':'Resultado indisponível'),statusClass=finished?(passed?'is-approved':'is-review'):(attempt.status==='open'?'is-open':'is-review'),searchable=esc(`${attempt.name||''} ${attempt.email||''}`.toLocaleLowerCase('pt-BR'));
      return `<tr data-results-row data-track="${esc(attempt.track_id)}" data-search="${searchable}"><td><strong>${esc(attempt.name)}</strong><small>${esc(attempt.email)}</small></td><td>${esc(trackFor(attempt.track_id)?.name||attempt.track_id)}</td><td>${attempt.result?formatPercent(attempt.result.score):'—'}</td><td><span class="results-status ${statusClass}">${statusLabel}</span>${attempt.result?.failedCritical?`<small>${attempt.result.failedCritical} regra(s) crítica(s) para revisar</small>`:''}</td><td>${formatDate(attempt.finished_at||attempt.started_at)}</td></tr>`;
    }).join('');
    commitView(`<section class="page-top"><div class="wrap"><span class="overline muted">${supervisor?'ACOMPANHAMENTO DA EQUIPE':'GESTÃO DA CAPACITAÇÃO'}</span><h1>${supervisor?'Resultados da sua equipe.':'Resultados que mostram evolução.'}</h1><p>${supervisor?'Acompanhe avaliações, notas e certificados da equipe nas trilhas liberadas para você.':'Veja quem avançou, como estão as avaliações e quais certificados já foram conquistados na ST1 Academy.'}</p><div class="results-heading-actions"><a class="button button-secondary" href="${base}/report.csv">Exportar resultados CSV ${icon('download')}</a>${supervisor?'':`<a class="button button-primary" href="#acessos">Gerenciar pessoas ${icon('arrow')}</a>`}</div></div></section><div class="wrap results-dashboard"><section class="results-kpis" aria-label="Indicadores gerais de resultados"><article class="results-kpi results-kpi--people"><span>Pessoas com avanço registrado</span><strong>${progressedPeople.size}</strong><small>Com avaliação concluída ou certificado</small></article><article class="results-kpi results-kpi--assessment"><span>Avaliações concluídas</span><strong>${completed.length}</strong><small>${attempts.length} tentativa(s) no total</small></article><article class="results-kpi results-kpi--score"><span>Nota média</span><strong>${averageScore(completed)}</strong><small>Somente avaliações concluídas</small></article><article class="results-kpi results-kpi--certificates"><span>Certificados emitidos</span><strong>${certificates.length}</strong><small>Registros oficiais da Academy</small></article></section><div class="results-outcome-strip" aria-label="Situação das avaliações"><div><strong>${approved.length}</strong><span>Aprovadas</span></div><div><strong>${needsReview.length}</strong><span>Precisam de revisão</span></div><div><strong>${inProgress.length}</strong><span>Em andamento</span></div><p>${supervisor?'Contagens restritas às pessoas e trilhas que você acompanha.':'Indicadores calculados com base em avaliações e certificados registrados no banco da Academy.'}</p></div><section class="results-panel" aria-labelledby="results-tracks-title"><div class="results-section-head"><div><span class="overline muted">VISÃO POR TRILHA</span><h2 id="results-tracks-title">Onde o time está avançando.</h2><p>Aprovações, avaliações em andamento e certificados emitidos em cada trilha.</p></div></div><div class="results-track-grid">${trackSummaries||'<div class="results-empty"><h3>Nenhuma trilha liberada para este acompanhamento.</h3><p>Peça ao Admin para revisar os acessos e as trilhas do perfil.</p></div>'}</div></section><section class="results-panel" aria-labelledby="results-certificates-title"><div class="results-section-head"><div><span class="overline muted">CONQUISTAS REGISTRADAS</span><h2 id="results-certificates-title">Certificados emitidos.</h2><p>Certificações conquistadas pelas pessoas desta visão, com acesso ao PDF registrado.</p></div><span class="results-section-count">${certificates.length} registro(s)</span></div><div class="results-certificate-list">${certificateCards||'<div class="results-empty"><h3>Nenhum certificado emitido nesta seleção.</h3><p>Quando uma pessoa concluir a avaliação e conquistar uma trilha, o certificado aparecerá aqui automaticamente.</p></div>'}</div></section><section class="results-panel" aria-labelledby="results-attempts-title"><div class="results-section-head"><div><span class="overline muted">HISTÓRICO DE AVALIAÇÕES</span><h2 id="results-attempts-title">Tentativas e resultados.</h2><p>Consulte notas, status e pontos críticos de cada tentativa registrada.</p></div><span class="results-section-count" data-results-count>${attempts.length} avaliação(ões)</span></div><div class="results-filter-bar"><label>Buscar pessoa<input type="search" data-results-search placeholder="Nome ou e-mail" autocomplete="off"></label><label>Trilha<select data-results-track><option value="all">Todas as trilhas</option>${tracks.map(track=>`<option value="${esc(track.id)}">${esc(track.name)}</option>`).join('')}</select></label></div><div class="results-table-scroll" tabindex="0" role="region" aria-label="Histórico de avaliações"><table class="results-table"><thead><tr><th>Pessoa</th><th>Trilha</th><th>Nota</th><th>Resultado</th><th>Data</th></tr></thead><tbody>${rows||'<tr><td colspan="5">Ainda não há tentativas de avaliação registradas.</td></tr>'}<tr data-results-no-match hidden><td colspan="5">Nenhuma avaliação corresponde aos filtros selecionados.</td></tr></tbody></table></div></section></div>`);
    const searchInput=main.querySelector('[data-results-search]'),trackSelect=main.querySelector('[data-results-track]'),resultRows=[...main.querySelectorAll('[data-results-row]')],countLabel=main.querySelector('[data-results-count]'),noMatch=main.querySelector('[data-results-no-match]');
    const filterRows=()=>{const query=(searchInput?.value||'').trim().toLocaleLowerCase('pt-BR'),track=trackSelect?.value||'all';let visible=0;for(const row of resultRows){const matches=row.dataset.search.includes(query)&&(track==='all'||row.dataset.track===track);row.hidden=!matches;if(matches)visible++;}if(countLabel)countLabel.textContent=`${visible} de ${attempts.length} avaliação(ões)`;if(noMatch)noMatch.hidden=visible>0||!attempts.length;};
    searchInput?.addEventListener('input',filterRows);trackSelect?.addEventListener('change',filterRows);
  }
  async function attemptAuthorizationPage(){
    if(!state.user||!['admin','supervisor'].includes(state.user.role)||!hasAccess('team_results'))return restricted('Acesso reservado à gestão.','Somente Admin ou Supervisor de equipe pode liberar novas tentativas.');
    const {items}=await api('/api/attempt-authorizations/blocked');
    if(location.hash!=='#autorizacoes')return;
    commitView('<section class="wrap library"><h1>Autorizar nova tentativa</h1><p>Após três tentativas, o Supervisor responsável ou Admin pode liberar apenas uma nova tentativa por vez. Toda autorização exige justificativa e fica registrada.</p>'+(items.length?items.map(item=>'<form class="quiz-ready-card" data-grant-attempt><h2>'+esc(item.name)+' · '+esc(item.title)+'</h2><p>'+item.used+' de '+item.max+' tentativas utilizadas. Avaliação: '+(item.kind==='quiz'?'Etapa ou desafio':'Certificação')+'.</p><input type="hidden" name="userId" value="'+esc(item.userId)+'"><input type="hidden" name="kind" value="'+esc(item.kind)+'"><input type="hidden" name="id" value="'+esc(item.assessmentId)+'"><label>Justificativa da liberação<textarea name="reason" minlength="10" maxlength="500" rows="3" required placeholder="Descreva o reforço ou acompanhamento realizado"></textarea></label><button class="button button-primary" type="submit">Autorizar mais uma tentativa</button><p class="form-error" role="alert" hidden></p></form>').join(''):'<div class="empty-panel"><h2>Nenhuma avaliação bloqueada na sua equipe.</h2><p>Os pedidos aparecerão aqui quando as três tentativas forem utilizadas.</p></div>')+'</section>');
  }
